struct WorkLine: Codable, Sendable, Identifiable {
    var engine: String = "v2proplus"
    var ref_id: String? = nil
    var emotion: String? = nil
    var gpt: String? = nil
    var sovits: String? = nil
    var top_k: Int = 15
    var top_p: Double = 1.0
    var temperature: Double = 1.0
    var repetition_penalty: Double = 1.35
    var seed: Int = -1
    var speed: Double = 1.0
    var fragment_interval: Double = 0.3
    var text_split_method: String = "cut5"
    var sample_steps: Int? = nil
    var aux_ref_ids: [String] = []
    var version: String? = nil
    var id: String
    var character: String = ""
    var text: String
    var lang: String = "ja"
    var pause_after: Double = 0.5
    var candidates: [AudioItem] = []
    var picked: String? = nil

    enum CodingKeys: String, CodingKey {
        case engine, ref_id, emotion, gpt, sovits, top_k, top_p, temperature, repetition_penalty
        case seed, speed, fragment_interval, text_split_method, sample_steps, aux_ref_ids, version
        case id, character, text, lang, pause_after, candidates, picked
    }

    init(
        engine: String = "v2proplus", ref_id: String? = nil, emotion: String? = nil,
        gpt: String? = nil, sovits: String? = nil, top_k: Int = 15, top_p: Double = 1.0,
        temperature: Double = 1.0, repetition_penalty: Double = 1.35, seed: Int = -1,
        speed: Double = 1.0, fragment_interval: Double = 0.3, text_split_method: String = "cut5",
        sample_steps: Int? = nil, aux_ref_ids: [String] = [], version: String? = nil,
        id: String, character: String = "", text: String, lang: String = "ja",
        pause_after: Double = 0.5, candidates: [AudioItem] = [], picked: String? = nil
    ) {
        self.engine = engine; self.ref_id = ref_id; self.emotion = emotion
        self.gpt = gpt; self.sovits = sovits; self.top_k = top_k; self.top_p = top_p
        self.temperature = temperature; self.repetition_penalty = repetition_penalty; self.seed = seed
        self.speed = speed; self.fragment_interval = fragment_interval; self.text_split_method = text_split_method
        self.sample_steps = sample_steps; self.aux_ref_ids = aux_ref_ids; self.version = version
        self.id = id; self.character = character; self.text = text; self.lang = lang
        self.pause_after = pause_after; self.candidates = candidates; self.picked = picked
    }

    init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        engine = try c.decodeIfPresent(String.self, forKey: .engine) ?? "v2pro"
        ref_id = try c.decodeIfPresent(String.self, forKey: .ref_id)
        emotion = try c.decodeIfPresent(String.self, forKey: .emotion)
        gpt = try c.decodeIfPresent(String.self, forKey: .gpt)
        sovits = try c.decodeIfPresent(String.self, forKey: .sovits)
        top_k = try c.decodeIfPresent(Int.self, forKey: .top_k) ?? 15
        top_p = try c.decodeIfPresent(Double.self, forKey: .top_p) ?? 1.0
        temperature = try c.decodeIfPresent(Double.self, forKey: .temperature) ?? 1.0
        repetition_penalty = try c.decodeIfPresent(Double.self, forKey: .repetition_penalty) ?? 1.35
        seed = try c.decodeIfPresent(Int.self, forKey: .seed) ?? -1
        speed = try c.decodeIfPresent(Double.self, forKey: .speed) ?? 1.0
        fragment_interval = try c.decodeIfPresent(Double.self, forKey: .fragment_interval) ?? 0.3
        text_split_method = try c.decodeIfPresent(String.self, forKey: .text_split_method) ?? "cut5"
        sample_steps = try c.decodeIfPresent(Int.self, forKey: .sample_steps)
        aux_ref_ids = try c.decodeIfPresent([String].self, forKey: .aux_ref_ids) ?? []
        version = try c.decodeIfPresent(String.self, forKey: .version)
        id = try c.decode(String.self, forKey: .id)
        text = try c.decode(String.self, forKey: .text)
        lang = try c.decodeIfPresent(String.self, forKey: .lang) ?? "ja"
        pause_after = try c.decodeIfPresent(Double.self, forKey: .pause_after) ?? 0.5
        candidates = try c.decodeIfPresent([AudioItem].self, forKey: .candidates) ?? []
        picked = try c.decodeIfPresent(String.self, forKey: .picked)
        character = try c.decodeIfPresent(String.self, forKey: .character)
            ?? candidates.first(where: { $0.id == picked })?.character
            ?? candidates.first?.character
            ?? ""
    }
}

